/bin/zsh -lc "rg -n '152512-080|152511-080|152510-080' docs/paivakirjat; python3 - <<'PY'
import zipfile,glob,xml.etree.ElementTree as E
for p in sorted(glob.glob('docs/kiertokirjeet/*')):
 print('\\nFILE',p)
 with zipfile.ZipFile(p) as z:
  r=E.fromstring(z.read('word/document.xml'))
  ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
  for para in r.findall('.//w:p',ns):
   print(''.join(t.text or '' for t in para.findall('.//w:t',ns)))
for p in sorted(glob.glob('docs/liitteet/*')):
 print('\\nFILE',p)
 with zipfile.ZipFile(p) as z:
  ns={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
  ss=[]
  if 'xl/sharedStrings.xml' in z.namelist():
   ss=[''.join(x.itertext()) for x in E.fromstring(z.read('xl/sharedStrings.xml'))]
  print(z.read('xl/workbook.xml').decode())
  for n in z.namelist():
   if n.startswith('xl/worksheets/sheet') and n.endswith('.xml'):
    print(n)
    for row in E.fromstring(z.read(n)).findall('.//s:row',ns):
     vals=[]
     for c in row.findall('s:c',ns):
      v=c.find('s:v',ns)
      val=v.text if v is not None else ''.join(c.find('s:is',ns).itertext()) if c.find('s:is',ns) is not None else ''
      if c.get('t')=='s':val=ss[int(val)]
      vals.append(c.get('r')+': '+val)
     print(' | '.join(vals))
PY"

